sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.currentDate = new Date();

    c.selectedDeadline = null;


    /* =========================================
       MONTH NAME
    ========================================= */

    c.monthTitle = function() {

        return c.currentDate.toLocaleString(
            'default',
            {
                month: 'long',
                year: 'numeric'
            }
        );

    };


    /* =========================================
       PREVIOUS MONTH
    ========================================= */

    c.previousMonth = function() {

        c.currentDate =
            new Date(
                c.currentDate.getFullYear(),
                c.currentDate.getMonth() - 1,
                1
            );

    };


    /* =========================================
       NEXT MONTH
    ========================================= */

    c.nextMonth = function() {

        c.currentDate =
            new Date(
                c.currentDate.getFullYear(),
                c.currentDate.getMonth() + 1,
                1
            );

    };


    /* =========================================
       TODAY
    ========================================= */

    c.goToday = function() {

        c.currentDate =
            new Date();

    };


    /* =========================================
       CALENDAR DAYS
    ========================================= */

    c.calendarDays = function() {

        var year =
            c.currentDate.getFullYear();

        var month =
            c.currentDate.getMonth();

        var first =
            new Date(year, month, 1);

        var last =
            new Date(year, month + 1, 0);

        var days = [];


        /*
         * Empty cells before first day
         */

        for (
            var i = 0;
            i < first.getDay();
            i++
        ) {

            days.push({
                empty: true
            });

        }


        /*
         * Actual month days
         */

        for (
            var day = 1;
            day <= last.getDate();
            day++
        ) {

            var date =
                new Date(
                    year,
                    month,
                    day
                );

            days.push({

                empty: false,

                day:
                    day,

                date:
                    date,

                deadlines:
                    c.deadlinesForDate(date),

                today:
                    c.isToday(date)

            });

        }


        return days;

    };


    /* =========================================
       DEADLINES FOR DATE
    ========================================= */

    c.deadlinesForDate = function(date) {

        var deadlines =
            c.data.deadlines || [];

        return deadlines.filter(
            function(deadline) {

                if (!deadline.due) {
                    return false;
                }

                /*
                 * ServiceNow internal date:
                 * YYYY-MM-DD HH:mm:ss
                 */

                var datePart =
                    deadline.due.substring(
                        0,
                        10
                    );

                var year =
                    date.getFullYear();

                var month =
                    ('0' +
                        (date.getMonth() + 1))
                        .slice(-2);

                var day =
                    ('0' +
                        date.getDate())
                        .slice(-2);

                var calendarDate =
                    year +
                    '-' +
                    month +
                    '-' +
                    day;

                return (
                    datePart ===
                    calendarDate
                );

            }
        );

    };


    /* =========================================
       TODAY CHECK
    ========================================= */

    c.isToday = function(date) {

        var today =
            new Date();

        return (
            date.getFullYear() ===
                today.getFullYear() &&

            date.getMonth() ===
                today.getMonth() &&

            date.getDate() ===
                today.getDate()
        );

    };


    /* =========================================
       SELECT DEADLINE
    ========================================= */

    c.selectDeadline = function(deadline) {

        c.selectedDeadline =
            deadline;

    };


    c.closeDeadline = function() {

        c.selectedDeadline =
            null;

    };

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH DEADLINES CALENDAR
========================================================== */

.cm-deadlines-page {
  width: 100vw !important;
  max-width: 100vw !important;

  min-height: 100vh;
  min-height: 100svh;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  padding: 52px 20px 90px;

  background:
    linear-gradient(
      180deg,
      #FBF8EF 0%,
      #F5F7F0 100%
    );

  font-family:
    "DM Sans",
    "Segoe UI",
    Arial,
    sans-serif;

  color: #102E34;

  box-sizing: border-box;
}


.cm-deadlines-page *,
.cm-deadlines-page *::before,
.cm-deadlines-page *::after {
  box-sizing: border-box;
}


.cm-deadlines-container {
  width: 100%;
  max-width: 1240px;

  margin: 0 auto;
}


/* ==========================================================
   HEADER
========================================================== */

.cm-deadlines-header {
  margin-bottom: 30px;

  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 25px;
}


.cm-deadlines-eyebrow {
  display: inline-flex;

  margin-bottom: 13px;
  padding: 7px 14px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 11px;
  font-weight: 800;
}


.cm-deadlines-header h1 {
  margin: 0 0 7px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 36px;
  font-weight: 700;

  letter-spacing: -1px;
}


.cm-deadlines-header p {
  margin: 0;

  color: #617477;

  font-size: 13px;
}


.cm-back-dashboard {
  padding: 10px 17px;

  border: 1px solid #D2DED8;
  border-radius: 999px;

  background: #FFFFFF;

  color: #104E45 !important;

  font-size: 11px;
  font-weight: 800;

  text-decoration: none !important;
}


/* ==========================================================
   CALENDAR
========================================================== */

.cm-calendar-card {
  overflow: hidden;

  border: 1px solid #D2DED8;
  border-radius: 22px;

  background: #FFFFFF;

  box-shadow:
    0 8px 28px rgba(16, 78, 69, .07);
}


/* ==========================================================
   TOOLBAR
========================================================== */

.cm-calendar-toolbar {
  min-height: 80px;

  padding: 17px 20px;

  display: grid;

  grid-template-columns:
    1fr auto 1fr;

  align-items: center;

  gap: 20px;

  border-bottom: 1px solid #D2DED8;
}


.cm-calendar-toolbar h2 {
  margin: 0;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 20px;
  font-weight: 700;

  text-align: center;
}


.cm-calendar-navigation {
  display: flex;
  align-items: center;

  gap: 7px;
}


.cm-calendar-arrow,
.cm-today-button {
  height: 34px;

  border: 1px solid #D2DED8;

  background: #FFFFFF;

  color: #104E45;

  cursor: pointer;
}


.cm-calendar-arrow {
  width: 34px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  font-size: 22px;
  line-height: 1;
}


.cm-today-button {
  padding: 0 14px;

  border-radius: 999px;

  font-family: inherit;

  font-size: 10px;
  font-weight: 800;
}


.cm-calendar-arrow:hover,
.cm-today-button:hover {
  background: #EDF5E9;
}


/* ==========================================================
   LEGEND
========================================================== */

.cm-calendar-legend {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  gap: 14px;
}


.cm-legend-item {
  display: flex;
  align-items: center;

  gap: 5px;

  color: #617477;

  font-size: 9px;
  font-weight: 700;
}


.cm-legend-item i {
  width: 8px;
  height: 8px;

  display: block;

  border-radius: 50%;
}


.cm-legend-item i.active {
  background: #249D78;
}


.cm-legend-item i.completed {
  background: #718185;
}


.cm-legend-item i.expired {
  background: #B5502F;
}


/* ==========================================================
   WEEKDAYS
========================================================== */

.cm-calendar-weekdays {
  display: grid;

  grid-template-columns:
    repeat(7, minmax(0, 1fr));

  background: #F8FAF6;

  border-bottom: 1px solid #D2DED8;
}


.cm-calendar-weekdays div {
  padding: 11px;

  color: #718185;

  font-size: 9px;
  font-weight: 800;

  text-align: center;

  text-transform: uppercase;

  letter-spacing: .4px;
}


/* ==========================================================
   DAYS
========================================================== */

.cm-calendar-grid {
  display: grid;

  grid-template-columns:
    repeat(7, minmax(0, 1fr));

  background: #D2DED8;

  gap: 1px;
}


.cm-calendar-day {
  position: relative;

  min-height: 125px;

  padding: 9px;

  overflow: hidden;

  background: #FFFFFF;
}


.cm-empty-day {
  background: #FAFBF9;
}


.cm-day-number {
  min-height: 27px;

  display: flex;
  justify-content: flex-end;
}


.cm-day-number span {
  width: 26px;
  height: 26px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #506267;

  font-size: 10px;
  font-weight: 700;
}


.cm-calendar-day.cm-today
.cm-day-number span {
  background: #104E45;

  color: #FFFFFF;
}


/* ==========================================================
   DEADLINE EVENT
========================================================== */

.cm-day-deadlines {
  display: flex;
  flex-direction: column;

  gap: 5px;
}


.cm-deadline-event {
  width: 100%;

  padding: 7px 8px;

  display: flex;
  align-items: flex-start;

  gap: 6px;

  border: 0;
  border-radius: 8px;

  font-family: inherit;

  text-align: left;

  cursor: pointer;
}


.cm-deadline-event.active {
  background: #E7F4EC;

  color: #15564B;
}


.cm-deadline-event.completed {
  background: #EDF2EE;

  color: #506267;
}


.cm-deadline-event.expired {
  background: #FBEAE7;

  color: #A44832;
}


.cm-event-dot {
  width: 6px;
  height: 6px;

  margin-top: 4px;

  flex-shrink: 0;

  border-radius: 50%;

  background: currentColor;
}


.cm-event-content {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 1px;
}


.cm-event-content strong {
  overflow: hidden;

  font-size: 9px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}


.cm-event-content small {
  overflow: hidden;

  font-size: 8px;

  opacity: .85;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* ==========================================================
   NO DEADLINES
========================================================== */

.cm-no-deadlines {
  margin-top: 20px;

  padding: 35px;

  border: 1px solid #D2DED8;
  border-radius: 18px;

  background: #FFFFFF;

  text-align: center;
}


.cm-no-deadlines-icon {
  width: 55px;
  height: 55px;

  margin: 0 auto 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 17px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-no-deadlines-icon svg {
  width: 27px;
  height: 27px;
}


.cm-no-deadlines h3 {
  margin: 0 0 5px;

  color: #104E45;

  font-size: 16px;
}


.cm-no-deadlines p {
  margin: 0;

  color: #718185;

  font-size: 11px;
}


/* ==========================================================
   MODAL
========================================================== */

.cm-deadline-overlay {
  position: fixed;

  inset: 0;

  z-index: 99999;

  padding: 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(16, 46, 52, .48);

  backdrop-filter: blur(3px);
}


.cm-deadline-modal {
  position: relative;

  width: 100%;
  max-width: 440px;

  padding: 27px;

  border: 1px solid #D2DED8;
  border-radius: 22px;

  background: #FBF8EF;

  box-shadow:
    0 22px 65px rgba(16, 46, 52, .22);
}


.cm-modal-close {
  position: absolute;

  top: 14px;
  right: 15px;

  width: 31px;
  height: 31px;

  border: 0;
  border-radius: 50%;

  background: #EDF5E9;

  color: #104E45;

  font-size: 19px;

  cursor: pointer;
}


.cm-modal-icon {
  width: 47px;
  height: 47px;

  margin-bottom: 13px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 14px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-modal-icon svg {
  width: 23px;
  height: 23px;
}


.cm-modal-eyebrow {
  display: block;

  margin-bottom: 5px;

  color: #168C70;

  font-size: 8px;
  font-weight: 900;

  letter-spacing: .7px;
}


.cm-deadline-modal h3 {
  margin: 0 0 19px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 20px;
}


.cm-modal-details {
  overflow: hidden;

  border: 1px solid #D2DED8;
  border-radius: 14px;

  background: #FFFFFF;
}


.cm-modal-details > div {
  padding: 11px 13px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 15px;

  border-bottom: 1px solid #EDF2EE;
}


.cm-modal-details > div:last-child {
  border-bottom: 0;
}


.cm-modal-details span {
  color: #718185;

  font-size: 9px;
}


.cm-modal-details strong {
  color: #102E34;

  font-size: 10px;

  text-align: right;
}


.cm-modal-status.active {
  color: #168C70;
}


.cm-modal-status.completed {
  color: #506267;
}


.cm-modal-status.expired {
  color: #A44832;
}


/* ==========================================================
   MESSAGES
========================================================== */

.cm-deadline-warning,
.cm-deadline-success,
.cm-deadline-expired {
  margin-top: 15px;

  padding: 11px 13px;

  border-radius: 11px;

  font-size: 10px;
  line-height: 1.5;
}


.cm-deadline-warning {
  background: #FDF3DC;

  color: #795C18;
}


.cm-deadline-success {
  background: #E4F4EA;

  color: #14765C;
}


.cm-deadline-expired {
  background: #FBEAE7;

  color: #A44832;
}


.cm-modal-done {
  width: 100%;

  margin-top: 18px;
  padding: 10px 16px;

  border: 0;
  border-radius: 999px;

  background: #104E45;

  color: #FFFFFF;

  font-family: inherit;

  font-size: 10px;
  font-weight: 800;

  cursor: pointer;
}


/* ==========================================================
   RESPONSIVE
========================================================== */

@media (max-width: 800px) {

  .cm-calendar-toolbar {
    grid-template-columns: 1fr;

    text-align: center;
  }


  .cm-calendar-navigation,
  .cm-calendar-legend {
    justify-content: center;
  }


  .cm-calendar-toolbar h2 {
    grid-row: 1;
  }


  .cm-calendar-day {
    min-height: 95px;

    padding: 6px;
  }


  .cm-event-content small {
    display: none;
  }

}


@media (max-width: 600px) {

  .cm-deadlines-page {
    padding: 35px 10px 70px;
  }


  .cm-deadlines-header {
    align-items: flex-start;

    flex-direction: column;
  }


  .cm-deadlines-header h1 {
    font-size: 29px;
  }


  .cm-calendar-weekdays div {
    padding: 8px 2px;

    font-size: 7px;
  }


  .cm-calendar-day {
    min-height: 75px;

    padding: 4px;
  }


  .cm-day-number {
    min-height: 23px;
  }


  .cm-day-number span {
    width: 22px;
    height: 22px;

    font-size: 8px;
  }


  .cm-event-content strong {
    font-size: 7px;
  }


  .cm-event-dot {
    display: none;
  }


  .cm-deadline-event {
    padding: 5px 4px;
  }

}

sp_widget.script:
(function() {

    var DEADLINE_TABLE =
        'x_snc_campusmatch_campusmatch_deadline';

    data.deadlines = [];
    data.userName = gs.getUserDisplayName() || 'Student';

    var deadline = new GlideRecord(DEADLINE_TABLE);

    /*
     * Admin dashboard:
     * Show collection deadlines for all claims,
     * not only the currently logged-in user.
     */

    deadline.addQuery('deadline_type', 'collection');

    /*
     * Only show deadlines whose linked claim
     * has NOT completed the handover.
     */
    deadline.addQuery('claim.handover_completed', false);

    /*
     * Keep active / completed / expired deadline records
     * available for the calendar.
     */
    var statusQuery = deadline.addQuery('status', 'active');
    statusQuery.addOrCondition('status', 'completed');
    statusQuery.addOrCondition('status', 'expired');

    deadline.orderBy('due_date_time');
    deadline.query();

    while (deadline.next()) {

        var due = new GlideDateTime(
            deadline.getValue('due_date_time')
        );

        var start = new GlideDateTime(
            deadline.getValue('start_date_time')
        );

        data.deadlines.push({

            sys_id:
                deadline.getUniqueValue(),

            number:
                deadline.getDisplayValue('number') || '',

            item:
                deadline.getDisplayValue('item') ||
                'CampusMatch Item',

            itemId:
                deadline.getValue('item') || '',

            claim:
                deadline.getDisplayValue('claim') || '',

            status:
                deadline.getValue('status') || '',

            statusDisplay:
                deadline.getDisplayValue('status') || '',

            start:
                start.getValue(),

            startDisplay:
                deadline.getDisplayValue('start_date_time') || '',

            due:
                due.getValue(),

            dueDisplay:
                deadline.getDisplayValue('due_date_time') || ''

        });

    }

})();
